(1, 1, 'Cinematique du point materiel', 'cinematique-point', 'Vecteurs position, vitesse, acceleration en coordonnees cartesiennes et cylindriques.', 'Contenu detaille du cours de cinematique...', '/assets/downloads/fiches-mecanique.pdf', 'l1', 1, '2026-08-13 21:23:45'),
